INSERT INTO concept_description VALUES
    (1,1,'Anemia due to bleeding or a hemorrhagic process.','en',7,'2004-01-01 00:00:00.0',24839,null,'ecd63692-07fe-102c-b5fa-0017a47871b2'),
    (2,2,'Anemia, due to the destruction or dissolution of red blood cells, with subsequent release of hemoglobin.','en',24839,'2004-01-01 00:00:00.0',5,null,'ecd63b56-07fe-102c-b5fa-0017a47871b2'),
    (3,3,'Anemia not due to other causes listed within the system.','en',7,'2004-01-01 07:00:00.0',5,'2011-11-17 15:52:14.0','ecd63ea8-07fe-102c-b5fa-0017a47871b2'),
    (4,3,'Anemia not due to other causes listed within the system.','fr',12,'2006-06-07 23:35:25.0',24839,'2011-11-17 15:52:14.0','ecd641aa-07fe-102c-b5fa-0017a47871b2'),
    (5,4,'An abrupt and/or progressive worsening of symptoms of shortness of breath, wheezing, chest tightness, or some combination of these with associated respiratory distress.','en',7,'2004-01-01 00:00:00.0',5,'2011-11-17 15:52:15.0','ecd644c0-07fe-102c-b5fa-0017a47871b2'),
    (6,5,'A chronic respiratory disease, arising from allergies or inflammation, that is characterized by sudden recurring attacks of labored breathing, chest constriction, and coughing.','en',1,'2004-01-01 00:00:00.0',7,'2011-11-16 11:12:48.0','ecd647e0-07fe-102c-b5fa-0017a47871b2'),
    (7,6,'subcutaneous immunization for TB; converts PPD to positive','en',12,'2004-01-01 00:00:00.0',7,'2010-12-08 11:11:18.0','ecd64f88-07fe-102c-b5fa-0017a47871b2'),
    (8,7,'Small, hard, pathological concretions, composed chiefly of cholesterol, calcium salts, and bile pigments, formed in the gallbladder or in a bile duct.','en',6,'2004-01-01 00:00:00.0',5,null,'ecd652b2-07fe-102c-b5fa-0017a47871b2'),
    (9,8,'Gallbladder or biliary duct problems not specified.','en',1,'2004-01-01 00:00:00.0',1,null,'ecd655c8-07fe-102c-b5fa-0017a47871b2'),
    (10,9,'serum glucose, elevated in diabetes','en',6,'2004-01-01 00:00:00.0',12,null,'ecd658e8-07fe-102c-b5fa-0017a47871b2'),
    (11,10,'Lower respiratory infection of the bronchial tubes, acute.','en',24839,'2004-01-01 00:00:00.0',7,null,'ecd65bea-07fe-102c-b5fa-0017a47871b2'),
    (12,11,'Lower respiratory infection of the bronchial tubes, recurrent.','en',1,'2004-01-01 00:00:00.0',24839,null,'ecd65eec-07fe-102c-b5fa-0017a47871b2'),
    (13,12,'An examination using irradiation for imaging the chest.','en',1,'2004-01-01 07:00:00.0',1,'2011-11-17 15:52:40.0','ecd66220-07fe-102c-b5fa-0017a47871b2'),
    (14,13,'methods for preventing pregnancy','en',5,'2004-01-01 00:00:00.0',7,null,'ecd66554-07fe-102c-b5fa-0017a47871b2'),
    (15,14,'Diarrhea due to amoebic infection.  Parasites can enter the body through food or water and settle in the digestive system. Parasites that cause diarrhea include Giardia lamblia, Entamoeba histolytica, and Cryptosporidium.','en',6,'2004-04-02 07:00:00.0',24839,'2011-11-17 15:52:17.0','ecd66888-07fe-102c-b5fa-0017a47871b2'),
    (16,15,'Diarrhea due to cholera.','en',12,'2004-04-02 00:00:00.0',5,null,'ecd66a90-07fe-102c-b5fa-0017a47871b2'),
    (17,16,'Diarrhea due to an unspecified cause.','en',6,'2004-01-01 00:00:00.0',5,'2011-11-17 15:52:21.0','ecd66c70-07fe-102c-b5fa-0017a47871b2'),
    (18,17,'Vaccination against diptheria and tetanus (IM).','en',1,'2004-01-01 00:00:00.0',6,null,'ecd66e50-07fe-102c-b5fa-0017a47871b2'),
    (19,18,'first vaccination for diptheria, pertussis (whooping cough), and tetanus (IM)','en',7,'2004-01-01 00:00:00.0',6,null,'ecd67026-07fe-102c-b5fa-0017a47871b2'),
    (20,19,'second vaccination for diptheria, pertussis (whooping cough), and tetanus (IM)','en',7,'2004-01-01 00:00:00.0',6,null,'ecd671f2-07fe-102c-b5fa-0017a47871b2'),
    (21,20,'third vaccination for diptheria, pertussis (whooping cough), and tetanus (IM)','en',24839,'2004-01-01 07:00:00.0',7,'2011-11-16 11:12:43.0','ecd673f0-07fe-102c-b5fa-0017a47871b2'),
    (22,21,'The iron-containing respiratory pigment in red blood cells of vertebrates, consisting of about 6 percent heme and 94 percent globin.','en',12,'2004-01-01 07:00:00.0',7,'2011-11-17 15:52:39.0','ecd675d0-07fe-102c-b5fa-0017a47871b2'),
    (23,22,'Vaccination against hepatitis A (IM).','en',5,'2004-01-01 00:00:00.0',7,null,'ecd6779c-07fe-102c-b5fa-0017a47871b2'),
    (24,23,'first vaccination against hepatitis B (IM).  Use concept 782.','en',5,'2004-01-01 00:00:00.0',7,'2010-12-08 11:24:55.0','ecd67972-07fe-102c-b5fa-0017a47871b2'),
    (25,24,'second vaccination against hepatitis B (IM)','en',1,'2004-01-01 00:00:00.0',7,null,'ecd67b3e-07fe-102c-b5fa-0017a47871b2'),
    (26,25,'third vaccination against hepatitis B (IM)','en',7,'2004-01-01 00:00:00.0',6,null,'ecd67d14-07fe-102c-b5fa-0017a47871b2'),
    (27,26,'Liver infection with hepatitis A virus ("infectious hepatitis").','en',1,'2004-01-01 00:00:00.0',24839,null,'ecd67ee0-07fe-102c-b5fa-0017a47871b2'),
    (28,27,'Liver infection with hepatitis B virus ("serum hepatitis").','en',5,'2004-01-01 00:00:00.0',5,null,'ecd680ac-07fe-102c-b5fa-0017a47871b2'),
