    (31,29,'Liver infection with an unknown organism or unspecified non-infectious liver inflammation.','fr',7,'2006-06-07 14:47:53.0',5,'2011-11-16 11:12:48.0','ecd68584-07fe-102c-b5fa-0017a47871b2'),
    (32,30,'patient infected with the HIV virus','en',6,'2004-01-01 00:00:00.0',7,null,'ecd686d8-07fe-102c-b5fa-0017a47871b2'),
    (33,31,'Services requested during a clinical encounter.','en',24839,'2006-02-10 17:08:45.0',5,null,'ecd68822-07fe-102c-b5fa-0017a47871b2'),
    (34,32,'Peripheral smear study for malarial parasites is the gold standard in diagnosing malarial infection. It involves collection of a blood smear, staining and examination of the the red blood cells for intracellular malarial parasites.','en',24839,'2004-01-01 00:00:00.0',6,'2011-11-17 15:52:14.0','ecd6896c-07fe-102c-b5fa-0017a47871b2'),
    (35,33,'mild infection with malaria protozoa','en',5,'2004-01-01 00:00:00.0',1,null,'ecd68ab6-07fe-102c-b5fa-0017a47871b2'),
    (36,34,'severe infection with malaria protozoa','en',5,'2004-01-01 00:00:00.0',5,null,'ecd68c00-07fe-102c-b5fa-0017a47871b2'),
    (37,35,'febrile illness believed to be malaria, but unconfirmed','en',24839,'2004-01-01 00:00:00.0',12,null,'ecd68d40-07fe-102c-b5fa-0017a47871b2'),
