INSERT INTO role VALUES
    ('Accompagnateur','Community health worker','d2fcb33e-2700-102b-80cb-0017a47871b2'),
    ('Accompagnateur Leader','Responsible for overseeing up to 30 Accompagnateurs','d2fcb604-2700-102b-80cb-0017a47871b2'),
    ('AdditionsFor1_9','Hack because permissions and roles don\'t seem to work in 1_9','d4299028-f419-4537-a5f6-0b12c532ac41'),
    ('Adherence Research Encounters Admin','Psychosocial Research Encounters role allows you to manage a set of forms and encounters.  these include adherence, psychosocial, ruhengeri, and pill count forms and encounters','b0a840bd-cbb2-4bc8-af75-1926c8ee7d86'),
    ('Anonymous','Privileges for non-authenticated users.','774b2af3-6437-4e5a-a310-547554c7c65c'),
    ('Authenticated','Privileges gained once authentication has been established.','f7fd42ef-880e-40c5-972d-e4ae7c990de2'),
    ('Clinician','Users who are a part of direct patient care.','d2fcbb5e-2700-102b-80cb-0017a47871b2'),
    ('Data Assistant','Clerks who perform data entry and produces reports.','d2fcbf8c-2700-102b-80cb-0017a47871b2'),
    ('Data Manager','User who maintains clinical data stored within the OpenMRS repository.','d2fcc14e-2700-102b-80cb-0017a47871b2'),
    ('HIV Patient Provider','This is for use with the HIV Flowsheets to restrict provider lists','048e8f30-1763-4d1d-9de4-133161b83efb'),
    ('Informatics Manager','User who maintains the local installation of the OpenMRS repository.','d2fcc31a-2700-102b-80cb-0017a47871b2'),
    ('Manage Passwords','Manage Passwords','f17dba9a-be05-4aea-963b-94e14980917a'),
    ('Manage Synchronization','Manage Synchronization','44d06437-cf8f-44c1-a3b4-47dc02bfb885'),
    ('NCD Provider','Non-communicable disease clinicians.','a1d4bb3d-b3bf-4a49-85ee-4e247c84e05c'),
    ('Oncology Provider','Oncology Provider','32624202-8afe-4019-854c-161ea43f4d34'),
    ('Pediatric Program Manager','Manager of pediatric programs','d2fcc4d2-2700-102b-80cb-0017a47871b2'),
    ('Pre Print Primary Care Registration Barcodes','allows user to pre-print primary care registration barcodes','55dd5069-8d31-4c91-a938-9c6bfb1d3035'),
    ('Priority Patient Provider','A provider who specializes in giving the highest quality of treatment to the patients most in need','4b59d6a2-0908-4343-ad1a-8f32b70da85b'),
    ('Program Manager','Has permission to view most/all data, but no permission for entry or editing.','d2fcc68a-2700-102b-80cb-0017a47871b2'),
    ('Provider','Health care provider','8d94f280-c2cc-11de-8d13-0010c6dffd0f'),
    ('Run Reports','Gives the user the ability to run reports','17094cb0-59f3-4e81-a799-199a5eefda91'),
    ('Safe Everything','Hack because permissions and roles don\'t seem to work in 1_9','d7be04fa-4640-4a79-a5d9-f4c6d7bddaaa'),
    ('Social Worker','Social Worker','d2fcc9fa-2700-102b-80cb-0017a47871b2'),
    ('System Developer','The same as system developer, except for privileges that allow hard deletes in the API.  Some module-related privileges may be missing.','8d94f852-c2cc-11de-8d13-0010c6dffd0f');
